-- b110: AI skills as DATA (F5). invokeSkill reads this table at runtime — a new skill is an INSERT, a retired
-- skill is active=false; ZERO code change. Platform-global config (no entity_id, no RLS) — like standards/config tables.
-- Additive + self-healing: lib/ai.js self-heals to its in-code SEED until this runs. Seeds the 24 in-use skills
-- (the 3 truly-orphaned skills — incoterm-advice, spec-draft, profile-prefill — were dropped from code and are NOT seeded).
CREATE TABLE IF NOT EXISTS ai_skill (
  skill_id   text PRIMARY KEY,
  category   text NOT NULL,
  gate       text NOT NULL DEFAULT 'confirm',
  kind       text NOT NULL,
  format     text,                                  -- 'json' for form-fill skills (else NULL = prose)
  label      text NOT NULL,
  system     text NOT NULL,                         -- the instruction / system prompt
  vertical   text NOT NULL DEFAULT 'universal',
  active     boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON ai_skill TO cb_app;   -- runtime reads only; INSERT/UPDATE (add/retire a skill) is a governance/admin action

ON CONFLICT (skill_id) DO UPDATE SET
  category=EXCLUDED.category, gate=EXCLUDED.gate, kind=EXCLUDED.kind, format=EXCLUDED.format,
  label=EXCLUDED.label, system=EXCLUDED.system, active=true, updated_at=now();
